{
  "hypotheses": [
    {
      "text": "IBM's sic_code in edgar.company_profiles contains leading or trailing whitespace (or invisible characters) that prevents an exact match with the sic_code values in company_dns.sic_codes_table.",
      "how_to_test": "SELECT cik, entity_name, sic_code, LENGTH(sic_code) AS raw_len, LENGTH(TRIM(sic_code)) AS trimmed_len FROM edgar.company_profiles WHERE cik = 51143; -- IBM. Then check if TRIM(sic_code) exists in the reference: SELECT 1 FROM company_dns.sic_codes_table WHERE sic_code = TRIM((SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143 LIMIT 1));"
    },
    {
      "text": "IBM's sic_code is stored as a numeric value without leading zeros (e.g., 3571) while the reference table expects a zero‑padded string format (e.g., '03571'), causing a mismatch on equality join.",
      "how_to_test": "SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143; -- get raw value. Then test if left‑padding to 4 or 5 characters yields a match: SELECT 1 FROM company_dns.sic_codes_table WHERE sic_code = LPAD((SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143), 4, '0');"
    },
    {
      "text": "The SIC code reported for IBM in edgar.company_profiles is obsolete or no longer present in the company_dns.sic_codes_table reference list (which may only contain currently active SICs).",
      "how_to_test": "SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143; -- IBM's sic. Then verify absence: SELECT NOT EXISTS (SELECT 1 FROM company_dns.sic_codes_table WHERE sic_code = (SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143));"
    },
    {
      "text": "IBM's company_profiles row has a NULL or empty sic_code (perhaps because IBM reports primarily via NAICS and the SIC field is blank), so the join produces no matches.",
      "how_to_test": "SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143; -- check for NULL or ''. Then count rows where sic_code IS NULL OR sic_code = '' for IBM."
    },
    {
      "text": "IBM appears multiple times in edgar.company_profiles (e.g., due to successive filings) with differing sic_code values, and none of those values match any entry in the reference table, resulting in zero rows after the join.",
      "how_to_test": "SELECT sic_code, COUNT(*) AS cnt FROM edgar.company_profiles WHERE cik = 51143 GROUP BY sic_code ORDER BY cnt DESC; -- list distinct sic codes. Then test each against the reference: SELECT sic_code FROM (SELECT DISTINCT sic_code FROM edgar.company_profiles WHERE cik = 51143) s WHERE NOT EXISTS (SELECT 1 FROM company_dns.sic_codes_table r WHERE r.sic_code = s.sic_code);"
    }
  ]
}
